def sha(data): return hashlib.sha256(data).hexdigest()

def main():
    root=Path(__file__).resolve().parent
    if not (root/'frontend/package.json').exists() or not (root/'.venv/bin/python').exists():
        raise SystemExit('STOP: copy into ~/RB-ITOS-AI; project or venv missing')
    decoded={rel:zlib.decompress(base64.b85decode(data)) for rel,data in PAYLOAD.items()}
    changes={}
    for rel, expected in BASELINE.items():
        path=root/rel
        if not path.is_file(): raise SystemExit(f'STOP: missing {rel}; nothing changed')
        actual=sha(path.read_bytes())
        if actual==sha(decoded[rel]): continue
        if actual!=expected: raise SystemExit(f'STOP: {rel} differs from reviewed baseline; nothing changed')
        changes[rel]=decoded[rel]
    if not changes:
        print('Already applied');return
    backup=root/'data/backups'/('hilega-fast-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ'))
    backup.mkdir(parents=True,exist_ok=False)
    dist=root/'frontend/dist'
    if dist.exists(): shutil.copytree(dist,backup/'dist')
    for rel,data in changes.items():
        saved=backup/rel;saved.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(root/rel,saved)
        target=root/rel;staged=target.with_name(target.name+'.hilega-fast.tmp');staged.write_bytes(data);staged.replace(target)
    checks=[
        ([str(root/'.venv/bin/python'),'-m','pytest','-q','tests/test_hilega_directional_live_shadow_ui_v1.py','tests/test_hilega_directional_candle_ui_v1.py','tests/test_storage_api.py'],root),
        (['npm','run','build'],root/'frontend'),
        (['git','diff','--check'],root),
    ]
    try:
        for cmd,cwd in checks:
            print('Running:', ' '.join(cmd),flush=True);subprocess.run(cmd,cwd=cwd,check=True)
    except (subprocess.CalledProcessError,OSError) as exc:
        for rel in changes: shutil.copy2(backup/rel,root/rel)
        if (backup/'dist').exists():
            if dist.exists(): shutil.rmtree(dist)
            shutil.copytree(backup/'dist',dist)
        print('STOP: validation failed; source and dist restored; services untouched',file=sys.stderr)
        raise SystemExit(1) from exc
    print('PASS: frontend built; API/worker untouched. API-only restart required for new fast routes.')
    print('Backup:',backup)

if __name__=='__main__': main()
